-- The Swamp Club video's description was rewritten in platform-videos on
-- 2026-10-23, after the stream; content/ on main still has the pre-stream
-- placeholder. The backfill builds description_doc from content/, so apply this
-- to platform-videos after it. The doc is the live description converted with
-- @rawkodeacademy/rich-text (fromMarkdown, mdx: false, breaks: true).
UPDATE `videos` SET
	`description_doc` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nick Stinemates (go-to-market at Swamp Club, and the \"S\" in SWAMP) joins Rawkode Live to take me from a fresh install to working "},{"type":"text","text":"Swamp","marks":[{"type":"bold"}]},{"type":"text","text":" automations in a single session."}]},{"type":"paragraph","content":[{"type":"text","text":"Swamp is a framework for building with AI by encoding how you work with your systems as reusable behaviours. Instead of an agent rediscovering your repo, your analytics or your secrets every time, it learns once, writes a deterministic TypeScript extension, and calls it as a tool from then on. That makes it faster and cheaper, and it gives the same result every run."}]},{"type":"paragraph","content":[{"type":"text","text":"In this live session, we:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run "},{"type":"text","text":"swamp start","marks":[{"type":"code"}]},{"type":"text","text":" and hand Codex a plain-English task: triage open, neglected issues on the Rawkode Academy GitHub"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pull a GitHub extension from the Swamp Club extension store and see how behaviours map Zod schemas and methods to tool calls"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Query the snapshots Swamp captures with "},{"type":"text","text":"swamp data query","marks":[{"type":"code"}]},{"type":"text","text":", and run behaviours directly without an LLM"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Turn the triage into a workflow with a 4 AM cron trigger on "},{"type":"text","text":"swamp serve","marks":[{"type":"code"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Have Swamp build a PostHog extension from scratch to find the most-watched videos on the website"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep credentials in 1Password through vault extensions, so secrets are injected just in time and never reach the model"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Switch from Codex to Claude Code on the same workspace, and talk through triggering workflows from GitHub webhooks"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tour the Swamp Club leaderboard, the Lab issue tracker and the pricing model"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Expect a few wrong turns, including a flaky connection and a stubborn Codex sandbox. That''s how we learn."}]},{"type":"paragraph","content":[{"type":"text","text":"Whether you want to automate a home lab, a release process or the worst part of your day, this is a practical look at making AI agents repeatable."}]}]}'
WHERE `id` = 'rez4r4sbaaog76765ijmdpli';
